export const capturedOriginalTests = {
  "tests/test-markdown-owned-assets.js": "#!/usr/bin/env node\nconst assert = require(\"node:assert/strict\");\nconst fs = require(\"node:fs\");\nconst os = require(\"node:os\");\nconst path = require(\"node:path\");\nconst { execFileSync } = require(\"node:child_process\");\nconst assets = require(\"../dist/knowledge/markdown-assets\");\nconst store = require(\"../dist/knowledge/filestore\");\nconst { attachMarkdownAssetsToSyncBundle } = require(\"../dist/sync/sync-server\");\n\nconst root = fs.mkdtempSync(path.join(os.tmpdir(), \"pkm-owned-assets-\"));\nconst extension = path.resolve(__dirname, \"..\");\ntry {\n  store.setStorePath(root);\n  for (const area of [\"skills\", \"notes\", \"papers\"]) {\n    const areaRoot = path.join(root, area);\n    const write = (key, title, content, category) => {\n      if (area === \"skills\") store.skillUpsert({ name: title, previousName: key.split(\"/\").pop(), content, category });\n      else if (area === \"notes\") store.noteUpsert({ slug: key, title, content, category, type: \"general\", tags: [] });\n      else store.paperUpsert({ slug: key, title, content, category });\n    };\n    write(\"Team/Design\", \"Design\", \"Original\", \"Team\");\n    const relative = assets.saveMarkdownAsset(root, area, \"Team/Design.md\", \"plot one.png\", Buffer.from(\"image\"));\n    assert.equal(relative, \"Design.assets/plot%20one.png\");\n    assert.throws(() => assets.saveMarkdownAsset(root, area, \"Team/Design.md\", \"plot one.png\", Buffer.from(\"overwrite\")), /already exists/);\n    assert.throws(() => assets.saveMarkdownAsset(root, area, \"../escape.md\", \"x.png\", Buffer.from(\"x\")), /Invalid/);\n    const special = assets.saveMarkdownAsset(root, area, \"Team/Design.md\", \"plot(1)#one.png\", Buffer.from(\"special\"));\n    assert.equal(special, \"Design.assets/plot%281%29%23one.png\");\n    fs.appendFileSync(path.join(areaRoot, \"Team\", \"Design.md\"), \"\\n![nested [label]](Design.assets/plot(1)%23one.png)\");\n    assert.throws(() => assets.editMarkdownAsset(root, area, \"Team/Design.md\", \"Team/Design.assets/plot(1)#one.png\"), /referenced/);\n    fs.writeFileSync(path.join(areaRoot, \"Team\", \"Design.assets\", \"dangling\"), \"\");\n    fs.unlinkSync(path.join(areaRoot, \"Team\", \"Design.assets\", \"dangling\"));\n    fs.symlinkSync(path.join(root, \"missing-outside\"), path.join(areaRoot, \"Team\", \"Design.assets\", \"dangling\"));\n    assert.throws(() => assets.saveMarkdownAsset(root, area, \"Team/Design.md\", \"dangling\", Buffer.from(\"escape\")), /Symbolic links/);\n    fs.unlinkSync(path.join(areaRoot, \"Team\", \"Design.assets\", \"dangling\"));\n    fs.unlinkSync(path.join(areaRoot, \"Team\", \"Design.assets\", \"plot(1)#one.png\"));\n    fs.mkdirSync(path.join(areaRoot, \"Team\", \"_assets\"), { recursive: true });\n    fs.writeFileSync(path.join(areaRoot, \"Team\", \"_assets\", \"legacy.png\"), \"old-shared\");\n    const content = `![plot](${relative})\\n![old](_assets/legacy.png)\\n\\`![code](${relative})\\``;\n    write(\"Team/Design\", \"Design\", content, \"Team\");\n    assets.saveMarkdownAsset(root, area, \"Team/Design.md\", \"diagram.mmd\", Buffer.from(\"graph LR\\nA-->B\"));\n    assert(!store.folderList(area).some(folder => folder.includes(\".assets\")), \"Resources are not content categories\");\n    assert.equal(assets.referencedMarkdownAssets(root, area, \"Team/Design.md\", content).length, 3, \"Unreferenced owned diagrams travel with their document\");\n\n    store.knowledgeMarkdownCopy(area, \"Team/Design.md\", \"Team/Copy.md\");\n    const copy = fs.readFileSync(path.join(areaRoot, \"Team\", \"Copy.md\"), \"utf8\");\n    assert(copy.includes(\"Copy.assets/plot%20one.png\"));\n    assert(!copy.includes(\"_assets/legacy.png\"), \"A copied document owns its legacy attachments without rewriting the source\");\n    assert(fs.readFileSync(path.join(areaRoot, \"Team\", \"Design.md\"), \"utf8\").includes(\"_assets/legacy.png\"));\n    assert.equal(fs.readFileSync(path.join(areaRoot, \"Team\", \"Copy.assets\", \"diagram.mmd\"), \"utf8\"), \"graph LR\\nA-->B\");\n    assert.notEqual(store.parseStoreFrontmatter(copy).fm.knowledgeId,\n      store.parseStoreFrontmatter(fs.readFileSync(path.join(areaRoot, \"Team\", \"Design.md\"), \"utf8\")).fm.knowledgeId);\n    assert.throws(() => store.knowledgeMarkdownCopy(area, \"Team/Design.md\", \"Team/Copy.md\"), /already exist/);\n\n    write(\"Team/Design\", \"Renamed\", content, \"Moved\");\n    const movedPath = path.join(areaRoot, \"Moved\", \"Renamed.md\");\n    const moved = fs.readFileSync(movedPath, \"utf8\");\n    assert(moved.includes(\"Renamed.assets/plot%20one.png\"));\n    assert(!moved.includes(\"../Team/_assets/legacy.png\"), \"Legacy resources migrate into the document's owned directory on move\");\n    assert.equal(assets.referencedMarkdownAssets(root, area, \"Moved/Renamed.md\", moved).filter(asset =>\n      fs.readFileSync(asset.fullPath, \"utf8\") === \"old-shared\").length, 1);\n    assert(!fs.existsSync(path.join(areaRoot, \"Team\", \"_assets\", \"legacy.png\")), \"Both the copied and moved documents now own their attachment bytes\");\n    assert(moved.includes(\"`![code](Design.assets/plot%20one.png)`\"));\n    assert(fs.existsSync(path.join(areaRoot, \"Moved\", \"Renamed.assets\", \"plot one.png\")));\n    assert(!fs.existsSync(path.join(areaRoot, \"Team\", \"Design.assets\")));\n\n    fs.writeFileSync(path.join(areaRoot, \"Other.md\"), \"![shared](Moved/Renamed.assets/plot%20one.png)\");\n    assert.throws(() => store.knowledgePathMoveToTrash(area, \"Moved/Renamed.md\"), /shared/);\n    assert.throws(() => assets.editMarkdownAsset(root, area, \"Moved/Renamed.md\", \"Moved/Renamed.assets/plot one.png\", \"new.png\"), /shared/);\n    fs.unlinkSync(path.join(areaRoot, \"Other.md\"));\n    assets.editMarkdownAsset(root, area, \"Moved/Renamed.md\", \"Moved/Renamed.assets/plot one.png\", \"new.png\");\n    assert(fs.readFileSync(movedPath, \"utf8\").includes(\"Renamed.assets/new.png\"));\n    assert.throws(() => assets.editMarkdownAsset(root, area, \"Moved/Renamed.md\", \"Moved/Renamed.assets/new.png\"), /referenced/);\n    assets.editMarkdownAsset(root, area, \"Moved/Renamed.md\", \"Moved/Renamed.assets/diagram.mmd\");\n    assert(!fs.existsSync(path.join(areaRoot, \"Moved\", \"Renamed.assets\", \"diagram.mmd\")));\n    store.writeKnowledgeMarkdown(area, \"Moved/Renamed.md\", undefined, fs.readFileSync(movedPath, \"utf8\"));\n    assert(store.knowledgeSyncDeletionRecords().some(record => record.path === `${area}/Moved/Renamed.assets/diagram.mmd`),\n      \"Saving the parent does not erase an earlier resource deletion intent\");\n    assert(store.knowledgeSyncDeletionRecords().some(record => record.path === `${area}/Moved/Renamed.assets/plot one.png`),\n      \"Resource rename records deletion of its previous path\");\n\n    const before = fs.readFileSync(movedPath);\n    const entry = store.knowledgePathMoveToTrash(area, \"Moved/Renamed.md\");\n    assert.equal(entry.assetsPath, \"Moved/Renamed.assets\");\n    assert(!fs.existsSync(movedPath));\n    assert(!fs.existsSync(path.join(areaRoot, \"Moved\", \"Renamed.assets\")));\n    assert(store.knowledgeSyncDeletionRecords().some(record => record.path === `${area}/Moved/Renamed.assets/new.png`));\n    const restore = () => area === \"skills\" ? store.skillTrashRestore(entry.id) : store.knowledgeTrashRestore(area, entry.id);\n    const metadataPath = path.join(areaRoot, \".trash\", entry.id, \"metadata.json\");\n    const metadata = fs.readFileSync(metadataPath, \"utf8\");\n    fs.writeFileSync(metadataPath, JSON.stringify({ ...JSON.parse(metadata), assetsPath: \"Unrelated.assets\" }));\n    assert.equal(restore().ok, false, \"Inconsistent resource ownership metadata cannot restore into an unrelated directory\");\n    assert(!fs.existsSync(movedPath), \"Invalid metadata is rejected before restoring any document\");\n    fs.writeFileSync(metadataPath, metadata);\n    fs.mkdirSync(path.join(areaRoot, \"Moved\", \"Renamed.assets\"), { recursive: true });\n    assert.equal(restore().ok, false, \"Resource collision does not partially restore a document\");\n    assert(!fs.existsSync(movedPath));\n    fs.rmdirSync(path.join(areaRoot, \"Moved\", \"Renamed.assets\"));\n    assert.equal(restore().ok, true);\n    assert.deepEqual(fs.readFileSync(movedPath), before);\n    assert(!store.knowledgeSyncDeletionRecords().some(record => record.path === `${area}/Moved/Renamed.assets/new.png`));\n    assert(store.knowledgeSyncDeletionRecords().some(record => record.path === `${area}/Moved/Renamed.assets/diagram.mmd`),\n      \"Restoring the parent only restores resources in its payload, not previously deleted diagrams\");\n    assert(store.knowledgeSyncDeletionRecords().some(record => record.path === `${area}/Moved/Renamed.assets/plot one.png`));\n    assets.saveMarkdownAsset(root, area, \"Moved/Renamed.md\", \"diagram.mmd\", Buffer.from(\"explicitly restored diagram\"));\n    assert(!store.knowledgeSyncDeletionRecords().some(record => record.path === `${area}/Moved/Renamed.assets/diagram.mmd`),\n      \"Explicit recreation cancels deletion intent for that resource\");\n    assert(store.knowledgeSyncDeletionRecords().some(record => record.path === `${area}/Moved/Renamed.assets/plot one.png`),\n      \"Recreating one resource does not cancel another resource's deletion intent\");\n    assets.editMarkdownAsset(root, area, \"Moved/Renamed.md\", \"Moved/Renamed.assets/diagram.mmd\");\n\n    fs.writeFileSync(path.join(areaRoot, \"Team\", \"_assets\", \"manual.png\"), \"manual migration\");\n    fs.appendFileSync(movedPath, \"\\n![manual](../Team/_assets/manual.png)\");\n    const preview = assets.previewMarkdownAssetMigration(root, area, \"Moved/Renamed.md\");\n    assert.equal(preview.copies.length, 1);\n    fs.appendFileSync(movedPath, \"\\nNew edit\");\n    assert.throws(() => assets.applyMarkdownAssetMigration(root, preview), /changed after/);\n    const fresh = assets.previewMarkdownAssetMigration(root, area, \"Moved/Renamed.md\");\n    assets.applyMarkdownAssetMigration(root, fresh);\n    assert(!fs.existsSync(path.join(areaRoot, \"Team\", \"_assets\", \"legacy.png\")), \"Later migration does not resurrect an earlier orphan\");\n    assert(!fs.existsSync(path.join(areaRoot, \"Team\", \"_assets\", \"manual.png\")), \"Migration removes an original once its last reference is owned\");\n    assert(store.knowledgeSyncDeletionRecords().some(record => record.path === `${area}/Team/_assets/manual.png`));\n    assert(!fs.readFileSync(movedPath, \"utf8\").includes(\"../Team/_assets/legacy.png\"));\n\n    const result = store.storeEntryMove(area, \"Moved/Renamed.md\", \"Final\");\n    assert.equal(result.ok, true, result.error);\n    assert(fs.existsSync(path.join(areaRoot, \"Final\", \"Renamed.assets\", \"new.png\")));\n    assert(fs.readFileSync(path.join(areaRoot, \"Final\", \"Renamed.md\"), \"utf8\").includes(\"Renamed.assets/new.png\"));\n    const bridge = execFileSync(process.execPath,\n      [path.join(extension, \"resources/knowledge_mutations.js\"), extension, root],\n      { input: JSON.stringify({ operation: \"write-markdown\", area, path: \"Bridge/Renamed.md\", previous: \"Final/Renamed.md\",\n        content: fs.readFileSync(path.join(areaRoot, \"Final\", \"Renamed.md\"), \"utf8\") }), encoding: \"utf8\" });\n    assert.equal(JSON.parse(bridge).ok, true);\n    assert(fs.existsSync(path.join(areaRoot, \"Bridge\", \"Renamed.assets\", \"new.png\")), \"MCP and UI share the resource move implementation\");\n    fs.symlinkSync(path.join(root, \"outside\"), path.join(areaRoot, \"Bridge\", \"Renamed.assets\", \"linked\"));\n    assert.throws(() => assets.referencedMarkdownAssets(root, area, \"Bridge/Renamed.md\", \"\"), /Symbolic links/);\n    fs.unlinkSync(path.join(areaRoot, \"Bridge\", \"Renamed.assets\", \"linked\"));\n    const bundle = attachMarkdownAssetsToSyncBundle(area === \"skills\"\n      ? { skills: [{ name: \"Renamed\", metadata: { category: \"Bridge\" }, content: fs.readFileSync(path.join(areaRoot, \"Bridge\", \"Renamed.md\"), \"utf8\") }] }\n      : { [area]: [{ slug: \"Bridge/Renamed\", title: \"Renamed\", category: \"Bridge\", content: fs.readFileSync(path.join(areaRoot, \"Bridge\", \"Renamed.md\"), \"utf8\") }] });\n    assert(bundle.assets.some(asset => asset.path === \"Bridge/Renamed.assets/new.png\"), \"All types export the exact document path, without duplicating Research categories\");\n    const importRoot = path.join(root, \"isolated-import\");\n    assets.importMarkdownAssetBundle(importRoot, bundle.assets, assets.markdownBundleDocuments(bundle), \"Incoming\");\n    assert.equal(fs.readFileSync(path.join(importRoot, area, \"Incoming\", \"Bridge\", \"Renamed.assets\", \"new.png\"), \"utf8\"), \"image\");\n    const invalid = JSON.parse(JSON.stringify(bundle.assets)); invalid[0].digest = \"sha256:invalid\";\n    assert.throws(() => assets.importMarkdownAssetBundle(importRoot, invalid, assets.markdownBundleDocuments(bundle)), /checksum/);\n    const foreign = JSON.parse(JSON.stringify(bundle.assets)); foreign[0].path = \"Other.assets/private.png\";\n    assert.throws(() => assets.importMarkdownAssetBundle(importRoot, foreign, assets.markdownBundleDocuments(bundle)), /not owned/);\n    const removed = store.knowledgePathMoveToTrash(area, \"Bridge/Renamed.md\");\n    const deletion = area === \"skills\" ? store.skillTrashDelete(removed.id) : store.knowledgeTrashDelete(area, removed.id);\n    assert.equal(deletion.ok, true);\n    assert(!fs.existsSync(path.join(areaRoot, \".trash\", removed.id)));\n    const folder = store.storeEntryMove(area, \"Team\", \"Archive\");\n    assert.equal(folder.ok, true, folder.error);\n    assert(fs.existsSync(path.join(areaRoot, \"Archive\", \"Team\", \"Copy.assets\", \"plot one.png\")));\n    assert(fs.readFileSync(path.join(areaRoot, \"Archive\", \"Team\", \"Copy.md\"), \"utf8\").includes(\"Copy.assets/\"));\n    assert(!fs.existsSync(path.join(areaRoot, \"Archive\", \"Team\", \"_assets\", \"legacy.png\")));\n    const promotion = store.folderDeletePromote(area, \"Archive/Team\");\n    assert.equal(promotion.ok, true, promotion.error);\n    assert(fs.existsSync(path.join(areaRoot, \"Archive\", \"Copy.assets\", \"plot one.png\")));\n    assert(!fs.existsSync(path.join(areaRoot, \"Archive\", \"_assets\", \"legacy.png\")));\n    assert(fs.readFileSync(path.join(areaRoot, \"Archive\", \"Copy.md\"), \"utf8\").includes(\"Copy.assets/\"));\n  }\n  const bundle = attachMarkdownAssetsToSyncBundle({ notes: [{ slug: \"Archive/Copy\", content: \"![plot](Copy.assets/plot%20one.png)\" }] });\n  assert(bundle.assets.some(asset => asset.path === \"Archive/Copy.assets/diagram.mmd\"));\n} finally {\n  fs.rmSync(root, { recursive: true, force: true });\n}\nconsole.log(\"Owned Markdown resources: all three content types, copy/move/rename, shared guards, Trash/restore, preview/apply, MCP bridge and bundle transport OK\");\n",
  "tests/test-todo-board.js": "const {test}=require(\"node:test\");\nconst assert=require(\"node:assert/strict\");\nconst fs=require(\"node:fs\");\nconst os=require(\"node:os\");\nconst path=require(\"node:path\");\nconst {spawnSync,spawn}=require(\"node:child_process\");\nconst store=require(\"../dist/knowledge/filestore\");\nconst {saveMarkdownAsset}=require(\"../dist/knowledge/markdown-assets\");\nconst {readTodoBoard}=require(\"../dist/knowledge/todo-board\");\nconst item=(id,extra={})=>({id,title:id,goal:\"User value\",scope:\"Board fixture\",acceptance:[\"Exact result\"],state:\"Planning\",evidence:[],...extra});\nconst user={id:\"user:local\",role:\"user\"};\nfunction fixture(t) {\n  const root=fs.mkdtempSync(path.join(os.tmpdir(),\"pkm-board-\"));\n  t.after(()=>fs.rmSync(root,{recursive:true,force:true}));\n  store.setStorePath(root);\n  return root;\n}\nfunction bridge(root,request) {\n  const result=spawnSync(process.execPath,[path.resolve(__dirname,\"../resources/knowledge_mutations.js\"),path.resolve(__dirname,\"..\"),root],{input:JSON.stringify(request),encoding:\"utf8\"});\n  return result.status===0?JSON.parse(result.stdout):{error:result.stderr};\n}\ntest(\"dedicated Board is discoverable when empty; generic Markdown and assets cannot change authoritative tasks\",t=>{\n  const root=fixture(t),slug=\"Project/Board\";\n  const empty=store.todoBoardCreate(slug,\"Board\",\"Project\");\n  assert.equal(store.noteGet(slug).documentKind,\"todo-board\");\n  assert.equal(store.noteWorkItemNotes().notes[0].count,0);\n  let state=store.noteWorkItemCommand(slug,empty.digest,{action:\"create\",item:item(\"task\")},user);\n  assert.equal(state.items[0].history[0].actorId,\"user:local\");\n  const markdown=fs.readFileSync(path.join(root,\"notes\",slug+\".md\"),\"utf8\");\n  assert(!markdown.includes(\"pkm-work-item\"));\n  assert.throws(()=>store.noteUpsert({slug,title:\"Board\",category:\"Project\",content:\"~~~pkm-work-item\\n{}\\n~~~\",type:\"todo\",tags:[]}),/cannot be edited as Markdown/);\n  assert.throws(()=>store.writeKnowledgeMarkdown(\"notes\",slug+\".md\",undefined,\"# Replaced\"),/cannot be edited as Markdown/);\n  assert.throws(()=>store.writeKnowledgeMarkdown(\"notes\",\"Forged.md\",undefined,'---\\ndocumentKind: \"todo-board\"\\n---\\n'),/creation/);\n  assert.throws(()=>store.noteWorkItemUpsert(slug,state.digest,item(\"replacement\")),/lifecycle commands/);\n  assert.throws(()=>saveMarkdownAsset(root,\"notes\",slug+\".md\",\"pkm-todo-board.json\",Buffer.from(\"{}\")),/reserved/);\n  assert.equal(bridge(root,{operation:\"write-markdown\",area:\"notes\",path:slug+\".md\",content:\"# Forged\"}).error.includes(\"cannot be edited as Markdown\"),true);\n  fs.appendFileSync(path.join(root,\"notes\",slug+\".md\"),\"\\n~~~pkm-work-item\\n\"+JSON.stringify(item(\"forged\"))+\"\\n~~~\\n\");\n  assert.deepEqual(store.noteWorkItemsRead(slug),state,\"raw Markdown edits cannot alter Board items or their digest\");\n  state=store.noteWorkItemCommand(slug,state.digest,{action:\"claim\",id:\"task\"},user);\n  assert.equal(state.items[0].state,\"WIP\");\n  const backing=path.join(root,\"notes\",slug+\".assets/pkm-todo-board.json\");\n  fs.unlinkSync(backing);\n  assert.throws(()=>store.noteWorkItemsRead(slug),/ENOENT/,\"missing authority cannot fall back to pasted Markdown blocks\");\n});\ntest(\"conversion requires a fresh explicit preview and preserves Story relations, acceptance and audit\",t=>{\n  fixture(t);\n  const slug=\"Legacy\";\n  store.noteUpsert({slug,title:slug,content:\"# Original history\\n\",type:\"todo\",tags:[]});\n  let state=store.noteWorkItemsRead(slug);\n  for(const record of [item(\"story\",{kind:\"UserStory\",storyStatus:\"draft\"}),item(\"child\",{parentId:\"story\"})]) {\n    state=store.noteWorkItemCommand(slug,state.digest,{action:\"create\",item:record},user);\n  }\n  const before=store.noteGet(slug).content,preview=store.todoBoardConversionPreview(slug);\n  assert.throws(()=>store.todoBoardConvert(slug,\"stale\"),/changed/);\n  const migrated=store.todoBoardConvert(slug,preview.digest);\n  assert.deepEqual(migrated.items,preview.items);\n  assert.equal(store.noteGet(slug).content,before,\"original Markdown retained as history only\");\n  assert.equal(store.noteGet(slug).documentKind,\"todo-board\");\n  assert.throws(()=>store.todoBoardConvert(slug,migrated.digest),/already/);\n  assert.throws(()=>store.noteWorkItemCommand(slug,preview.digest,{action:\"claim\",id:\"child\"},user),/changed/);\n});\ntest(\"Board authority follows rename, folders, Trash, restore and explicit export/import without sharing worker grants\",t=>{\n  fixture(t);\n  store.todoBoardCreate(\"Team/Board\",\"Board\",\"Team\");\n  let snapshot=store.noteWorkItemsRead(\"Team/Board\");\n  snapshot=store.noteWorkItemCommand(\"Team/Board\",snapshot.digest,{action:\"create\",item:item(\"task\",{ownerId:\"external:claude:reviewer\",owner:\"Claude reviewer\"})},user);\n  store.todoBoardGrantWorker(\"Team/Board\",snapshot.digest,\"external:claude:reviewer\");\n  store.noteMove(\"Team/Board\",\"Moved\");\n  assert.deepEqual(store.noteWorkItemsRead(\"Moved/Board\").items,snapshot.items);\n  const entry=store.knowledgePathMoveToTrash(\"notes\",\"Moved/Board.md\");\n  assert(entry);\n  store.knowledgeTrashRestore(\"notes\",entry.id);\n  assert.deepEqual(store.noteWorkItemsRead(\"Moved/Board\").items,snapshot.items);\n  const rows=store.noteExport();\n  assert.equal(rows[0].todoBoard.workers,undefined);\n  rows[0].slug=\"Imported/Board\";rows[0].category=\"Imported\";\n  assert.equal(store.noteImport(rows),1);\n  assert.deepEqual(store.noteWorkItemsRead(\"Imported/Board\").items,snapshot.items);\n  assert.throws(()=>store.noteImport([{slug:\"Imported/Board\",title:\"Board\",content:\"# Overwrite\"}]),/Cannot overwrite/);\n});\ntest(\"Board-scoped external worker tokens distinguish Agents, retain worker restrictions and rotate with CAS\",t=>{\n  const root=fixture(t),slug=\"Board\";\n  store.todoBoardCreate(slug,slug);\n  let state=store.noteWorkItemsRead(slug);\n  for(const [id,ownerId] of [[\"one\",\"external:copilot:one\"],[\"two\",\"external:claude:two\"]]) {\n    state=store.noteWorkItemCommand(slug,state.digest,{action:\"create\",item:item(id,{ownerId,owner:ownerId})},user);\n  }\n  const token=store.todoBoardGrantWorker(slug,state.digest,\"external:copilot:one\");\n  state=store.noteWorkItemsRead(slug);\n  assert(!fs.readFileSync(path.join(root,\"notes/Board.assets/pkm-todo-board.json\"),\"utf8\").includes(token));\n  assert.throws(()=>store.noteWorkItemExternalCommand(slug,state.digest,{action:\"claim\",id:\"one\"}),/another actor/);\n  assert.throws(()=>store.noteWorkItemExternalCommand(slug,state.digest,{action:\"claim\",id:\"two\"},token),/another actor/);\n  let result=bridge(root,{operation:\"work-item-command\",area:\"notes\",path:\"Board.md\",expectedDigest:state.digest,command:{action:\"claim\",id:\"one\"},workerToken:token});\n  assert(!result.error,result.error);\n  assert.equal(result.items[0].ownerId,\"external:copilot:one\");\n  state=store.noteWorkItemCommand(slug,result.digest,{action:\"edit\",item:{...result.items[0],reviewerIds:[\"user:local\"]}},user);\n  assert.throws(()=>store.noteWorkItemExternalCommand(slug,state.digest,{action:\"edit\",item:{...state.items[0],acceptance:[\"Weaken\"]}},token),/protected/);\n  const next=store.todoBoardGrantWorker(slug,state.digest,\"external:copilot:one\");\n  state=store.noteWorkItemsRead(slug);\n  assert.throws(()=>store.noteWorkItemExternalCommand(slug,state.digest,{action:\"claim\",id:\"one\"},token),/rotated/);\n  const done=store.noteWorkItemExternalCommand(slug,state.digest,{action:\"transition\",id:\"one\",state:\"Done\",outcome:\"Success\",evidence:[\"test://external\"]},next);\n  assert.equal(done.items[0].history.at(-1).actorId,\"external:copilot:one\");\n  assert.throws(()=>store.noteWorkItemExternalCommand(slug,done.digest,{action:\"accept\",id:\"one\",reason:\"Self review\"},next),/Only a user/);\n  store.todoBoardCreate(\"Other\",\"Other\");\n  assert.throws(()=>store.noteWorkItemExternalCommand(\"Other\",store.noteWorkItemsRead(\"Other\").digest,{action:\"claim\",id:\"one\"},next),/invalid for this Board/);\n});\ntest(\"Board JSON rejects invalid graph/duplicates instead of hiding corruption\",()=>{\n  assert.throws(()=>readTodoBoard(\"bad\"),/Invalid Todo Board JSON/);\n  for(const items of [[item(\"same\"),item(\"same\")],[item(\"child\",{parentId:\"missing\"})],[item(\"loop\",{dependsOn:[\"loop\"]})]]) {\n    assert.throws(()=>readTodoBoard(JSON.stringify({schema:\"pkm.todo-board/v1\",items})));\n  }\n});\ntest(\"competing Board commands across processes have exactly one CAS winner\",async t=>{\n  const root=fixture(t),slug=\"Race\";\n  store.todoBoardCreate(slug,slug);\n  const empty=store.noteWorkItemsRead(slug);\n  const before=store.noteWorkItemCommand(slug,empty.digest,{action:\"create\",item:item(\"race\")},user);\n  const command=()=>new Promise(resolve=>{\n    const child=spawn(process.execPath,[path.resolve(__dirname,\"../resources/knowledge_mutations.js\"),path.resolve(__dirname,\"..\"),root],{stdio:[\"pipe\",\"ignore\",\"pipe\"]});\n    let stderr=\"\";child.stderr.on(\"data\",chunk=>stderr+=chunk);\n    child.on(\"close\",code=>resolve({code,stderr}));\n    child.stdin.end(JSON.stringify({operation:\"work-item-command\",area:\"notes\",path:\"Race.md\",expectedDigest:before.digest,command:{action:\"claim\",id:\"race\"}}));\n  });\n  const results=await Promise.all([command(),command()]);\n  assert.equal(results.filter(result=>result.code===0).length,1);\n  assert.match(results.find(result=>result.code!==0).stderr,/changed/);\n});\n",
  "tests/test-knowledge-contracts.js": "#!/usr/bin/env node\nconst assert = require(\"assert\");\nconst fs = require(\"fs\");\nconst os = require(\"os\");\nconst path = require(\"path\");\nconst contracts = require(\"../dist/knowledge/knowledge-contracts.js\");\nconst store = require(\"../dist/knowledge/filestore.js\");\n\nconst first = contracts.nextKnowledgeIdentity(\n  undefined,\n  \"note\",\n  \"Project/Original\",\n  \"Project/Original\",\n  () => \"knowledge_0123456789abcdef01234567\",\n);\nassert.deepStrictEqual(first, {\n  schema: \"pkm.knowledge/v1\",\n  knowledgeId: \"knowledge_0123456789abcdef01234567\",\n  revision: 1,\n  aliases: [\"note:Project/Original\"],\n});\nconst moved = contracts.nextKnowledgeIdentity(first, \"note\", \"Project/Original\", \"Archive/Renamed\");\nassert.strictEqual(moved.knowledgeId, first.knowledgeId);\nassert.strictEqual(moved.revision, 2);\nassert.deepStrictEqual(moved.aliases, [\"note:Archive/Renamed\", \"note:Project/Original\"]);\nassert.strictEqual(contracts.compileKnowledgeIdentityV1(moved).ok, true);\nassert.strictEqual(contracts.compileKnowledgeIdentityV1({ ...moved, revision: 0 }).ok, false);\nassert.throws(() => contracts.legacyKnowledgeAlias(\"note\", \"../\\u0000\"), /control characters/);\nassert.strictEqual(contracts.compileKnowledgeLinksV1([{\n  relation: \"supports\",\n  target: \"pkm://knowledge/knowledge_0123456789abcdef01234567\",\n  mode: \"pinned\",\n  required: true,\n  targetRevision: \"7\",\n}]).ok, true);\nassert.strictEqual(contracts.compileKnowledgeLinksV1([{\n  relation: \"supports\",\n  target: \"notes/Project/Original\",\n  mode: \"floating\",\n  required: true,\n}]).ok, false);\nassert.strictEqual(contracts.compileKnowledgeLinksV1([{\n  relation: \"supports\",\n  target: \"pkm://knowledge/knowledge_0123456789abcdef01234567\",\n  mode: \"pinned\",\n  required: true,\n}]).ok, false);\nassert.deepStrictEqual(contracts.validateKnowledgeIdentitySet([\n  moved,\n  { ...moved, aliases: [\"note:Other\"] },\n  { ...first, knowledgeId: \"knowledge_aaaaaaaaaaaaaaaaaaaaaaaa\", aliases: moved.aliases },\n]).map(item => item.code).sort(), [\"alias-collision\", \"alias-collision\", \"duplicate-knowledge-id\"]);\n\nconst root = fs.mkdtempSync(path.join(os.tmpdir(), \"pkm-knowledge-contracts-\"));\ntry {\n  store.setStorePath(root);\n  store.noteUpsert({\n    slug: \"Project/Original\", title: \"Original\", content: \"body\", type: \"general\", tags: [], category: \"Project\",\n    links: [{\n      relation: \"supports\",\n      target: \"pkm://knowledge/knowledge_aaaaaaaaaaaaaaaaaaaaaaaa\",\n      mode: \"floating\",\n      required: false,\n    }],\n  });\n  const originalNote = store.noteGet(\"Project/Original\");\n  assert.match(originalNote.knowledgeId, /^knowledge_[a-f0-9]{24}$/);\n  assert.strictEqual(originalNote.revision, 1);\n  assert.strictEqual(originalNote.links[0].relation, \"supports\");\n  store.noteUpsert({\n    slug: originalNote.slug, title: \"Renamed\", content: \"body 2\", type: \"general\", tags: [], category: \"Archive\",\n  });\n  const renamedNote = store.noteGet(\"Archive/Renamed\");\n  assert.strictEqual(renamedNote.knowledgeId, originalNote.knowledgeId);\n  assert.strictEqual(renamedNote.revision, 2);\n  assert.deepStrictEqual(renamedNote.aliases, [\"note:Archive/Renamed\", \"note:Project/Original\"]);\n  assert.strictEqual(renamedNote.links[0].target, \"pkm://knowledge/knowledge_aaaaaaaaaaaaaaaaaaaaaaaa\");\n  assert.throws(() => store.noteUpsert({\n    slug: renamedNote.slug, title: \"Invalid Link\", content: \"body\", type: \"general\", tags: [], category: \"Archive\",\n    links: [{ relation: \"supports\", target: \"relative/path\", mode: \"floating\", required: false }],\n  }), /Invalid Knowledge links/);\n\n  store.skillUpsert({ name: \"Stable Skill\", content: \"v1\", category: \"One\" });\n  const originalSkill = store.skillGet(\"Stable Skill\");\n  store.skillUpsert({ name: \"Stable Skill\", content: \"v2\", category: \"Two\" });\n  const movedSkill = store.skillGet(\"Stable Skill\");\n  assert.strictEqual(movedSkill.knowledgeId, originalSkill.knowledgeId);\n  assert.deepStrictEqual(movedSkill.aliases, [\"skill:One/Stable Skill\", \"skill:Two/Stable Skill\"]);\n\n  store.paperUpsert({ slug: \"Topic/Original Research\", title: \"Original Research\", content: \"v1\", category: \"Topic\" });\n  const originalResearch = store.paperGet(\"Topic/Original Research\");\n  store.paperUpsert({ slug: originalResearch.slug, title: \"Moved Research\", content: \"v2\", category: \"Archive\" });\n  const movedResearch = store.paperGet(\"Archive/Moved Research\");\n  assert.strictEqual(movedResearch.knowledgeId, originalResearch.knowledgeId);\n  assert.deepStrictEqual(movedResearch.aliases, [\"research:Archive/Moved Research\", \"research:Topic/Original Research\"]);\n\n  console.log(\"Knowledge contracts: stable IDs, revisions, aliases, Note/Skill/Research moves OK\");\n} finally {\n  fs.rmSync(root, { recursive: true, force: true });\n}\n",
  "tests/test-retrieval-snapshot.js": "#!/usr/bin/env node\nconst assert = require(\"assert\");\nconst fs = require(\"fs\");\nconst os = require(\"os\");\nconst path = require(\"path\");\nconst { createRetrievalSnapshot } = require(\"../dist/retrieval/retrieval-snapshot.js\");\nconst storage = require(\"../dist/knowledge/storage.js\");\nconst extension = fs.readFileSync(path.join(__dirname, \"..\", \"src\", \"extension.ts\"), \"utf8\");\n\nconst groups = [\"Broker A\", \"Broker B\", \"Broker C\"].map((alias, index) => ({\n  subscriptionId: `sub-${index}`,\n  alias,\n  priority: index === 0 ? \"highest\" : index === 1 ? \"high\" : \"normal\",\n  publisher: `publisher-${index}`,\n  nodeId: `node-${index}`,\n  shareId: `share-${index}`,\n  revision: index + 1,\n  syncedAt: \"2026-09-16T00:00:00Z\",\n  items: [{ key: `remote-${index}`, title: `Remote ${index}`, path: `Team/Remote ${index}.md`, type: \"skills\",\n    pkmPath: `pkm://subscriptions/node-${index}/share-${index}/skills/Team/Remote%20${index}.md` }],\n}));\nconst sources = {\n  skills: [{ _key: \"Coding/Local Skill\", knowledgeId: \"knowledge_0123456789abcdef01234567\", revision: 3, name: \"Local Skill\", description: \"Local procedure\", content: \"skill body\", category: \"Coding\", tags: '[\"local\"]', priority: \"high\" }],\n  notes: [{ slug: \"Research/Local Note\", knowledgeId: \"knowledge_aaaaaaaaaaaaaaaaaaaaaaaa\", revision: 2, title: \"Local Note\", description: \"Observation\", content: \"note body\", category: \"Research\", type: \"observation\", tags: \"[]\" }],\n  papers: [\n    { slug: \"Papers/Parent\", knowledgeId: \"knowledge_cccccccccccccccccccccccc\", revision: 5, title: \"Parent Paper\", description: \"Prior art\", content: \"parent body\", topic: \"Retrieval\", conclusions: [\"bounded graph\"] },\n    { slug: \"Papers/Child\", knowledgeId: \"knowledge_dddddddddddddddddddddddd\", revision: 2, title: \"Child Paper\", description: \"Follow-up\", content: \"child body\", topic: \"Retrieval\", cites: [{ paper: \"Parent Paper\", note: \"builds on\" }] },\n  ],\n  scripts: [{ path: \"Scope/local.script\", knowledgeId: \"script_0123456789abcdef01234567\", file: \"local.script\", category: \"Scope\", lang: \"scope\", extension: \".script\", content: \"script body\" }],\n  recipes: [{ recipeId: \"recipe_local\", knowledgeId: \"knowledge_bbbbbbbbbbbbbbbbbbbbbbbb\", revision: 4,\n    name: \"Local Recipe\", description: \"Executable workflow\", category: \"Automation\",\n    executableDigest: \"c\".repeat(64), definition: { schema: \"pkm.workflow.definition/v1\", spec: { nodes: [] } } }],\n  subscriptionGroups: groups,\n  readSubscription: key => ({ contentType: \"skills\", content: `body:${key}`, provenance: { upstream: key } }),\n};\n\nconst first = createRetrievalSnapshot(sources);\nconst boardSources={...sources,notes:[{...sources.notes[0],documentKind:\"todo-board\",boardDigest:\"a\".repeat(64),content:\"Historical task falsely says Done\"}]};\nconst boardDocument=createRetrievalSnapshot(boardSources).documents.find(item=>item.content_type===\"note\");\nassert(!boardDocument.body.includes(\"falsely says Done\"),\"retrieval must not present historical Markdown as authoritative Board state\");\nassert(boardDocument.body.includes(\"note_work_items\")&&boardDocument.body.includes(\"note_work_item_command\"));\nassert.notStrictEqual(boardDocument.source_revision,createRetrievalSnapshot({...boardSources,notes:[{...boardSources.notes[0],boardDigest:\"b\".repeat(64)}]}).documents.find(item=>item.content_type===\"note\").source_revision);\nconst second = createRetrievalSnapshot({ ...sources, subscriptionGroups: [...groups].reverse() });\nassert.strictEqual(first.documents.length, 9, \"local Skill/Note/Research/Script/Recipe plus all three Brokers must share one index\");\nassert.strictEqual(first.corpus_revision, second.corpus_revision, \"corpus revision must not depend on input ordering\");\nassert.deepStrictEqual(first.documents.filter(item => item.read_only).map(item => item.provenance.broker), [\"Broker A\", \"Broker B\", \"Broker C\"]);\nassert.deepStrictEqual(first.documents.filter(item => item.read_only).map(item => item.metadata.source_priority), [\"highest\", \"high\", \"normal\"]);\nassert.strictEqual(first.documents.find(item => item.provenance.broker === \"Broker A\").provenance.source_priority, \"highest\");\nassert(first.documents.some(item => item.skill_id === \"skill:Coding/Local Skill\"\n  && item.knowledge_id === \"knowledge_0123456789abcdef01234567\"\n  && item.source_uri === \"pkm://knowledge/knowledge_0123456789abcdef01234567\"\n  && item.metadata.legacy_uri === \"pkm://skills/Coding/Local%20Skill\"));\nassert.strictEqual(first.documents.find(item => item.skill_id === \"skill:Coding/Local Skill\").metadata.priority, \"high\");\nassert(first.documents.some(item => item.skill_id === \"note:Research/Local Note\"\n  && item.knowledge_id === \"knowledge_aaaaaaaaaaaaaaaaaaaaaaaa\"\n  && item.source_uri === \"pkm://knowledge/knowledge_aaaaaaaaaaaaaaaaaaaaaaaa\"\n  && item.content_type === \"note\"));\nconst script = first.documents.find(item => item.content_type === \"script\");\nassert(script && script.source_id === \"pkm://script/script_0123456789abcdef01234567\"\n  && script.source_uri === script.source_id && script.skill_id === script.source_id\n  && script.metadata.legacy_uri === \"pkm://scripts/Scope/local.script\");\nconst movedScript = createRetrievalSnapshot({ ...sources, scripts: [{ ...sources.scripts[0], path: \"Scope/moved.script\", updatedAt: \"tomorrow\" }] }).documents.find(item => item.content_type === \"script\");\nassert.strictEqual(movedScript.source_id, script.source_id, \"moving a script must preserve its identity\");\nassert.strictEqual(movedScript.source_revision, script.source_revision, \"path and timestamp cannot change the content revision\");\nconst editedScript = createRetrievalSnapshot({ ...sources, scripts: [{ ...sources.scripts[0], content: \"new script body\" }] }).documents.find(item => item.content_type === \"script\");\nassert.strictEqual(editedScript.source_id, script.source_id);\nassert.notStrictEqual(editedScript.source_revision, script.source_revision, \"editing content must change its content revision\");\nconst root = fs.mkdtempSync(path.join(os.tmpdir(), \"pkm-script-identity-\"));\ntry {\n  storage.setStorePath(root);\n  fs.mkdirSync(path.join(root, \"scripts\", \"Scope\"), { recursive: true });\n  fs.writeFileSync(path.join(root, \"scripts\", \"Scope\", \"local.script\"), \"script body\");\n  const original = storage.scriptGet(\"Scope/local.script\");\n  const canonicalUri = `pkm://script/${original.knowledgeId}`;\n  const legacyId = `script_${require(\"crypto\").createHash(\"sha256\").update(\"Scope/local.script\").digest(\"hex\").slice(0, 24)}`;\n  assert.strictEqual(original.knowledgeId, legacyId, \"adopting a legacy Script must preserve its existing canonical URI\");\n  assert(fs.existsSync(storage.scriptIdentityFile(original.path)), \"identity must be persisted beside the source\");\n  const secondRoot = fs.mkdtempSync(path.join(os.tmpdir(), \"pkm-script-identity-peer-\"));\n  try {\n    fs.mkdirSync(path.join(secondRoot, \"scripts\", \"Scope\"), { recursive: true });\n    fs.writeFileSync(path.join(secondRoot, \"scripts\", \"Scope\", \"local.script\"), \"script body\");\n    storage.setStorePath(secondRoot);\n    assert.strictEqual(storage.scriptGet(\"Scope/local.script\").knowledgeId, original.knowledgeId,\n      \"independent machines must adopt the same legacy Script identity before the first sync\");\n  } finally {\n    storage.setStorePath(root);\n    fs.rmSync(secondRoot, { recursive: true, force: true });\n  }\n  assert.strictEqual(storage.scriptList().length, 1, \"sidecar must not appear as a Script\");\n  assert(storage.scriptMove(\"Scope/local.script\", \"Moved\"));\n  const moved = storage.scriptGet(canonicalUri);\n  assert.strictEqual(moved.knowledgeId, original.knowledgeId);\n  assert.strictEqual(moved.path, \"Moved/local.script\");\n  assert.strictEqual(storage.scriptGet(\"pkm://scripts/Scope/local.script\").knowledgeId, original.knowledgeId);\n  assert.strictEqual(storage.scriptGet(`pkm://script/${legacyId}`).knowledgeId, original.knowledgeId);\n  assert.strictEqual(storage.scriptGet(\"Scope/local.script\").knowledgeId, original.knowledgeId);\n  fs.writeFileSync(path.join(root, \"scripts\", \"Scope\", \"local.script\"), \"another script\");\n  assert.strictEqual(storage.scriptMove(\"Moved/local.script\", \"Scope\"), false, \"moving cannot overwrite a different Script\");\n  const replacement = storage.scriptGet(\"Scope/local.script\");\n  assert.notStrictEqual(replacement.knowledgeId, original.knowledgeId, \"a reused path cannot steal the moved Script's ID\");\n  assert.strictEqual(storage.scriptGet(\"pkm://scripts/Scope/local.script\").knowledgeId, original.knowledgeId,\n    \"the old URI continues to identify the moved Script after path reuse\");\n  const reusedExports = storage.scriptExport();\n  const reusedRoot = fs.mkdtempSync(path.join(os.tmpdir(), \"pkm-script-identity-reuse-\"));\n  try {\n    storage.setStorePath(reusedRoot);\n    assert.strictEqual(storage.scriptImport(reusedExports), 2);\n    assert.strictEqual(storage.scriptGet(\"Scope/local.script\").knowledgeId, replacement.knowledgeId);\n    assert.strictEqual(storage.scriptGet(\"pkm://scripts/Scope/local.script\").knowledgeId, original.knowledgeId,\n      \"export/import must not reassign a moved Script's old alias to its replacement\");\n  } finally {\n    storage.setStorePath(root);\n    fs.rmSync(reusedRoot, { recursive: true, force: true });\n  }\n  fs.rmSync(path.join(root, \"scripts\", \"Scope\", \"local.script\"));\n  fs.writeFileSync(path.join(root, \"scripts\", moved.path), \"edited body\");\n  assert.strictEqual(storage.scriptGet(canonicalUri).knowledgeId, original.knowledgeId);\n  assert.strictEqual(storage.scriptList().length, 1);\n  const exported = storage.scriptExport();\n  assert.strictEqual(exported[0].identity.knowledgeId, original.knowledgeId);\n  const importedRoot = fs.mkdtempSync(path.join(os.tmpdir(), \"pkm-script-identity-import-\"));\n  try {\n    storage.setStorePath(importedRoot);\n    assert.strictEqual(storage.scriptImport(exported), 1);\n    assert.strictEqual(storage.scriptGet(\"Moved/local.script\").knowledgeId, original.knowledgeId,\n      \"an unprefixed Script import preserves the source identity after a move\");\n    const updatedIdentity = { ...exported[0].identity, aliases: [...exported[0].identity.aliases, \"pkm://scripts/Before/local.script\"] };\n    assert.strictEqual(storage.scriptImport([{ ...exported[0], identity: updatedIdentity }]), 1);\n    assert.strictEqual(storage.scriptGet(\"pkm://scripts/Before/local.script\").knowledgeId, original.knowledgeId,\n      \"subsequent imports merge newly learned legacy aliases for the same Script\");\n    assert.strictEqual(storage.scriptImport([{ ...exported[0], category: \"Copy\", identity: undefined }]), 1);\n    assert.notStrictEqual(storage.scriptGet(\"Copy/local.script\").knowledgeId, original.knowledgeId,\n      \"a prefixed import creates an independent Script\");\n    assert.strictEqual(storage.scriptImport([{ ...exported[0], category: \"Other\" }]), 0,\n      \"the same identity cannot be imported under a second path\");\n  } finally {\n    storage.setStorePath(root);\n    fs.rmSync(importedRoot, { recursive: true, force: true });\n  }\n} finally {\n  storage.setStorePath(\"\");\n  fs.rmSync(root, { recursive: true, force: true });\n}\nconst childPaper = first.documents.find(item => item.skill_id === \"research:Papers/Child\");\nassert(childPaper && childPaper.content_type === \"research\"\n  && childPaper.source_id === \"pkm://knowledge/knowledge_dddddddddddddddddddddddd\"\n  && childPaper.source_revision === \"2\");\nassert.deepStrictEqual(childPaper.links, [{\n  relation: \"cites\",\n  target: \"pkm://knowledge/knowledge_cccccccccccccccccccccccc\",\n  mode: \"floating\",\n  required: false,\n}]);\nassert(first.documents.some(item => item.skill_id === \"recipe:recipe_local\"\n  && item.knowledge_id === \"knowledge_bbbbbbbbbbbbbbbbbbbbbbbb\"\n  && item.content_type === \"recipe\"\n  && item.source_uri === \"pkm://knowledge/knowledge_bbbbbbbbbbbbbbbbbbbbbbbb\"));\nassert(first.documents.filter(item => item.content_type === \"subscription\").every(item => item.skill_id === item.source_uri && item.provenance.provider === \"broker\"));\nconst changed = createRetrievalSnapshot({ ...sources, subscriptionGroups: groups.slice(0, 2) });\nassert.notStrictEqual(changed.corpus_revision, first.corpus_revision, \"unsubscribe must change the visible corpus revision\");\nassert.strictEqual(changed.documents.length, 8);\nconst reprioritized = createRetrievalSnapshot({ ...sources, subscriptionGroups: groups.map(group => ({ ...group, priority: \"normal\" })) });\nassert.notStrictEqual(reprioritized.corpus_revision, first.corpus_revision, \"source priority must invalidate the retrieval corpus\");\nassert.throws(() => createRetrievalSnapshot({\n  ...sources,\n  skills: [{ ...sources.skills[0], links: [{ relation: \"supports\", target: \"relative/path\", mode: \"floating\", required: true }] }],\n}), /Invalid Knowledge links/, \"invalid canonical links must fail instead of disappearing from the derived graph\");\nassert.match(extension, /scheduleRetrievalRefresh\\(context, 10_000\\)/, \"activation/runtime setup must defer the initial snapshot until first content can render\");\nassert.match(extension, /function scheduleRetrievalRefresh\\(context: vscode\\.ExtensionContext, delay = 5_000\\)/, \"repeated file events must coalesce before rebuilding the search index\");\nassert.match(extension, /title: \"PKM: Updating search index\"/, \"background search indexing must be visible without blocking the CatTree\");\nassert.match(extension, /onChanged:[\\s\\S]{0,500}scheduleRetrievalRefresh\\(context\\)/, \"Broker updates must refresh the Subscriber index\");\nassert.match(extension, /_watcherRefreshTimer = setTimeout[\\s\\S]{0,1200}scheduleRetrievalRefresh\\(context\\)/, \"local file updates must refresh the Subscriber index\");\nconsole.log(\"retrieval snapshot test: local Skill/Note/Research/Script/Recipe plus Broker partitions and canonical citations OK\");\n"
} as const;
